-- ASO INOVISION: complete database setup for Supabase.
-- Run this whole file once: Supabase dashboard > SQL Editor > New query > paste > Run.
-- It is safe to read top to bottom; each part has a comment.

-- 1. ADMINS --------------------------------------------------------------
create table if not exists public.admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  email text,
  created_at timestamptz not null default now()
);
alter table public.admins enable row level security;
create policy "admins can see their own row" on public.admins for select to authenticated using (user_id = auth.uid());

create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as
$$ select exists (select 1 from public.admins where user_id = auth.uid()) $$;
revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to anon, authenticated;

-- 2. WEBSITE CONTENT (public can read what is published; only admins can change) ---------
create table if not exists public.site_sections (
  key text primary key,
  value text not null,
  updated_at timestamptz not null default now()
);
create table if not exists public.services (
  id bigint generated by default as identity primary key,
  grp text not null,
  title text not null,
  description text not null,
  image text,
  featured boolean not null default false,
  sort integer not null default 100,
  published boolean not null default true
);
create table if not exists public.industries (
  id bigint generated by default as identity primary key,
  title text not null,
  description text not null,
  image text,
  sort integer not null default 100,
  published boolean not null default true
);
create table if not exists public.insights (
  id bigint generated by default as identity primary key,
  title text not null,
  summary text not null default '',
  body text not null default '',
  author_name text,
  author_title text,
  author_image text,
  cover_image text,
  published boolean not null default false,
  published_at timestamptz not null default now()
);
create table if not exists public.jobs (
  id bigint generated by default as identity primary key,
  title text not null,
  dept text not null default '',
  job_type text not null default 'Full-time',
  location text not null default 'Lagos',
  short text not null default '',
  overview text not null default '',
  responsibilities jsonb not null default '[]',
  requirements jsonb not null default '[]',
  is_intern boolean not null default false,
  "open" boolean not null default true,
  sort integer not null default 100
);

-- 3. FORM SUBMISSIONS (written only by the Edge Functions; read only by admins) -------------
create table if not exists public.consultations (
  id bigint generated by default as identity primary key,
  created_at timestamptz not null default now(),
  full_name text not null, email text not null, phone text not null, organisation text not null,
  job_title text, company_size text, industry text, service text, timeline text, budget text,
  contact_method text, preferred_time text, message text not null,
  status text not null default 'new',
  notes text
);
create table if not exists public.applications (
  id bigint generated by default as identity primary key,
  created_at timestamptz not null default now(),
  role text not null, full_name text not null, email text not null, phone text not null, location text,
  level text, department text,
  education text not null, experience text,
  linkedin text, x_handle text, facebook text, note text,
  cv_path text not null,
  status text not null default 'new',
  notes text
);

-- 4. ROW LEVEL SECURITY ---------------------------------------------------
alter table public.site_sections enable row level security;
alter table public.services      enable row level security;
alter table public.industries    enable row level security;
alter table public.insights      enable row level security;
alter table public.jobs          enable row level security;
alter table public.consultations enable row level security;
alter table public.applications  enable row level security;

create policy "anyone reads site text"          on public.site_sections for select using (true);
create policy "anyone reads published services" on public.services      for select using (published or public.is_admin());
create policy "anyone reads published industries" on public.industries  for select using (published or public.is_admin());
create policy "anyone reads published insights" on public.insights      for select using (published or public.is_admin());
create policy "anyone reads open jobs"          on public.jobs          for select using ("open" or public.is_admin());

create policy "admins manage site text"  on public.site_sections for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins manage services"   on public.services      for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins manage industries" on public.industries    for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins manage insights"   on public.insights      for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins manage jobs"       on public.jobs          for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins manage consultations" on public.consultations for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins manage applications"  on public.applications  for all to authenticated using (public.is_admin()) with check (public.is_admin());
-- consultations and applications have no public policy: visitors cannot read or write them directly.

-- 5. FILE STORAGE -----------------------------------------------------------
insert into storage.buckets (id, name, public) values ('site-media','site-media',true), ('cvs','cvs',false) on conflict (id) do nothing;
create policy "admins upload site media" on storage.objects for insert to authenticated with check (bucket_id = 'site-media' and public.is_admin());
create policy "admins update site media" on storage.objects for update to authenticated using (bucket_id = 'site-media' and public.is_admin());
create policy "admins delete site media" on storage.objects for delete to authenticated using (bucket_id = 'site-media' and public.is_admin());
create policy "admins read cvs"   on storage.objects for select to authenticated using (bucket_id = 'cvs' and public.is_admin());
create policy "admins delete cvs" on storage.objects for delete to authenticated using (bucket_id = 'cvs' and public.is_admin());
-- site-media is public (images on your website). cvs is private; applicants upload through the Edge Function only.

-- 6. STARTING CONTENT (what the website shows today) -------------------------
